"""Validate keys generated by :mod:`keygen`."""

import re


_KEY_PATTERN = re.compile(r"[A-Z0-9]{5}(?:-[A-Z0-9]{5}){2}")


def validate_key(key: str) -> bool:
	"""Return whether *key* matches the generated key format."""
	return isinstance(key, str) and _KEY_PATTERN.fullmatch(key) is not None


if __name__ == "__main__":
	import sys

	if len(sys.argv) != 2:
		raise SystemExit(f"Usage: {sys.argv[0]} KEY")

	raise SystemExit(0 if validate_key(sys.argv[1]) else 1)
